                    PT("06/p-sc5ff5fa2", "《金剛經》和《圓覺經》都屬於般若部，但是《金剛經》主要內容是給阿羅漢們講的分別心，所以從義理上看屬於方等部。《圓覺經》的主要內容是給菩薩們講的妄想和菩薩的修行，因此《圓覺經》比《金剛經》要高一個段次，對初學來說理解起來更難。", topic="圓覺經屬般若部高於金剛經"),
                    PT("06/p-sebfe6ec3", "到目前為止，在市面上能找到的《圓覺經》的解讀中，還沒有看到真正把《圓覺經》的核心內容講清楚的書，因為大部分人都是以凡夫的境界試圖去理解佛菩薩的世界，這是根本不可能的事情。", topic="市面解讀未講清圓覺核心"),
                    PT("06/p-s495462c3", "“圓覺”即圓滿覺悟。“修多羅”譯為契經。“了義”是究竟之意，現今的說法便是終極；與其相對的是“不了義”，不夠究竟。所以《大方廣圓覺修多羅了義經》就是指向圓滿覺悟的終極理論書。", topic="經名「圓覺」即圓滿覺悟"),
