            {
                "id": "xian-shan-shou-jing-ming",
                "title": "賢善首問：經名與功德",
                "body": [
                    "賢善首的兩問：此大乘教法叫什麼名字？應該怎樣奉持？",
                    "經文回答五個名稱：《大方廣圓覺陀羅尼》《修多羅了義》"
                    "《秘密王三昧》《如來決定境界》《如來藏自性差別》。",
                    "「大方廣」的拆解：從體、相、用三個維度詮釋眾生心性"
                    "——「大」指本體遍佈法界，「方」表示軌則規範，"
                    "「廣」意為作用周遍。",
                    "「十二部經」＝佛陀教法依敘述形式與內容分成的十二類"
                    "（又稱十二分教、十二分聖教）。",
                    "功德比較（經文）：用積滿三千大千世界的七寶佈施，"
                    "不如聽聞這部經的名字或一句義理；教導百恆河沙數眾生證阿羅漢果，"
                    "也不如宣說這部經半句偈子。",
                    "聽聞的門檻（經文）：聽經名而深信不疑的人，"
                    "不止在一佛二佛前種福田智慧，而是在如恆河沙數般多的佛前"
                    "種下善根，才能聽聞——佛囑付這些善男子守護末世眾生。",
                ],
                "quotes": [
                    PT("06/p-s4ccf9d8a", "於是賢善首菩薩在大眾中離座而起，頂禮佛足，右繞佛三圈，向佛長跪合掌，說道：“大悲世尊，廣為我們以及末世眾生開示這些不思議的修行方法，令我們開悟。世尊，此大乘教法叫什麼名字？應該怎樣修持奉行？眾生修習後可以得到什麼功德？我們怎樣保護奉持這部經的人？流通這部經典到什麼地方？”", topic="賢善首問經名等五事"),
                    PT("06/p-s8b5ba18f", "“這部經的名字叫《大方廣圓覺陀羅尼》，亦名《修多羅了義》，亦名《秘密王三昧》，亦名《如來決定境界》，亦名《如來藏自性差別》，你們應當奉行修持。”", topic="本經五個名稱"),
                    PT("06/p-s2e3bf10e", "《大方廣圓覺陀羅尼》中的“大方廣”，主要從體、相、用三個維度對眾生心性或佛性予以詮釋。其中，“大”指本體遍佈法界，“方”表示軌則規範，“廣”意為作用周遍，三者共同構成大乘經典的核心概念。諸多大乘佛經以“大方廣”為字首，此乃大乘佛經的通用名稱，例如《大方廣佛華嚴經》。“陀羅尼”意為法門，合起來即“圓滿覺悟的法門”。", topic="大方廣陀羅尼名相釋義"),
                    PT("06/p-s76603312", "“十二部經”，指佛陀的教法依敘述形式與內容分為十二種類，又稱十二分教、十二分聖教、十二分經。具體包括：", topic="十二部經名目"),
                    PT("06/p-sc559f2c0", "“善男子，假如有人只是用積滿三千大千世界的七寶去佈施，還不如有人聽聞這部經的名字或一句義理。善男子，假如有人能教導百恆河沙數般多的眾生證得阿羅漢果，也不如宣說這部經半句偈子。”", topic="聞經功德勝七寶布施"),
                    PT("06/p-s78c79517", "“善男子，如果有人聽到這部經的名字，深信不疑，應當知道此人不止在一佛二佛前種下福田智慧，而是在如恆河沙數般多的佛前種下種種善根，才能聽聞這部經的教法。你們這些善男子，應當守護末世中修持本經的修行者，不要讓惡魔及各種外道擾亂他們的身心，使他們產生退縮屈服之心。”", topic="囑守護末世修行者"),
                ],
                "check": {
                    "q": "本經的五個名稱？「大方廣」三個字各指什麼？",
                    "a": "大方廣圓覺陀羅尼／修多羅了義／秘密王三昧／如來決定境界／"
                         "如來藏自性差別。大＝體遍法界、方＝軌則、廣＝作用周遍。",
                },
            },
            {
                "id": "mo-fa-hu-chi-zong-jie",
                "title": "末法護持與全經總結",
                "body": [
                    "護法眾的出場：法會中火首金剛、摧碎金剛、尼藍婆金剛等八萬金剛"
                    "與眷屬頂禮佛足，稟告守護末世能堅定持守本經大乘教法的人；"
                    "大力鬼王吉槃荼與十萬鬼王也發願守護持經者，朝夕侍衛，"
                    "使其不生退縮屈服之心。",
                    "一個沒被直接回答的問題：本經流通的地區——佛沒有直接回答，"
                    "但本經出現於唐朝，唯有接受大乘教法的地區才能接受本經義理。",
                    "講經人的總結：閱讀本書前務必先讀《坐禪1》《坐禪2》，"
                    "建立宏觀框架，並瞭解由「諸佛同體」衍生出的業與菩薩的妄想境界"
                    "——如此才能正確領會本經最關鍵的三種圓覺法門。",
                    "《圓覺經》作為大乘伏藏，義理直指成佛之道；但佛有意對一些問題"
                    "不作解答——這是眾多大乘佛經的共性：佛是實語者，"
                    "但有些內容可選擇不予言說，需修行者在實修中自行感悟。",
                    "最後的迴向：把講解本經的功德迴向給讀過本書的有緣人，"
                    "以及幫助流通和佈施作者的善男信女——祝願有緣人此生業盡時都能證道，"
                    "求往生者得往生，求解脫者得解脫。",
                ],
                "quotes": [
                    PT("06/p-sac3a498c", "當時，法會中有火首金剛、摧碎金剛、尼藍婆金剛等八萬金剛和他們的眷屬離座而起，頂禮佛足，右繞佛三圈，對佛稟告道：“世尊，如果末世一切眾生中，有能夠堅定持守本經中的大乘教法的人，我們一定守護他們，就像保護自己的眼睛一樣。乃至他們的修行道場，我們金剛各自帶領自己的徒眾，從早到晚地守護著，使他們不退轉。令他們的家永遠沒有災難，疫病消滅，財寶豐足而不缺少。”", topic="八萬金剛發願守護"),
                    PT("06/p-s6230f00d", "當時，有大力鬼王，名吉槃荼，與十萬鬼王離座而起，頂禮佛足，右繞佛三圈，對佛稟告道：“世尊，我們也會守護修持這部經的人，朝夕侍衛，使他們不生起退縮屈服之心。他們的住所方圓一由旬之內，如果有鬼神侵犯，我們就把他們打碎成微塵般的粉末。”", topic="鬼王承諾護衛一由旬"),
                    PT("06/p-s42e7f89f", "答：佛沒有直接回答，但本經出現於唐朝，唯有接受大乘教法的地區才能接受本經中的義理。答案可想而知。", topic="流通地區佛未直答"),
                    PT("06/p-s6992b9e2", "再次強調，閱讀本書之前務必先研讀《坐禪1》和《坐禪2》。需對佛法構建基本的宏觀框架，同時瞭解由“諸佛同體”衍生出的業以及菩薩的妄想境界。如此，方能正確領會本書中最為關鍵的三種圓覺法門——奢摩他、三摩缽提、禪那，還能理解發菩提心的重要意義。", topic="總結勸先讀坐禪一二"),
                    PT("06/p-s1b1a290b", "《圓覺經》作為大乘伏藏，其義理直指成佛之道。然而，佛有意對一些問題不作出解答，這也是眾多大乘佛經的共性。佛是實語者，但有些內容可選擇不予言說，需修行者在實際的修行程序中自行感悟。故而，對外廣泛傳播的佛經，無論其義理多麼高深，終究只是引領眾生踏入真相世界的指引標識，而非真相本身。並且，佛在本經中也明確強調了善知識的重要性。所以，倘若一個人不進行實際修行，僅僅研究佛經，即便研究得再多，也只是原地踏步，甚至還會滋生貢高我慢之心。我們學習、研究佛經，旨在理解佛所闡釋的世界真相。理解之後，就要切實展開修行，真正做到與佛同行、與佛同願，方能與諸佛心心相印，在修心和消業方面持續取得進步。", topic="佛經是指引非真相本身"),
                    PT("06/p-sd11aef7a", "最後，把講解本經的功德迴向給所有讀過本書的有緣人，以及幫助流通和佈施作者的善男信女。祝願所有有緣人此生業盡時都能證道，求往生者得往生，求解脫者得解脫！", topic="講經功德迴向有緣人"),
                ],
                "check": {
                    "q": "佛為什麼對某些問題不直答？讀本經前的前置功課？",
                    "a": "佛是實語者，但有些內容不適合言說，需修行中自行感悟"
                         "（大乘經共性）。前置：先讀《坐禪1》《坐禪2》建框架。",
                },
            },
