                    "視眾生如己：菩薩摩訶薩觀所有眾生就像自己一樣，"
                    "知道肉都是從有生命的眾生中來的，怎麼能吃呢？",
                    "外道尚且不吃：路伽耶這樣的外道也執著於有無、斷常等二邊見，"
