                    PT("10/p-s6a3a6c0a", "那麼第二個，就是三大設定當中，初始設定當中第二個，是叫初妄無因。妄想會突然會生起，它是沒有原因的，這一點很重要。我們規定什麼是意識，什麼是不是意識，在這一條上就是命名上，或者概念的設定上，它就首先得要講清楚。", topic="次條初妄無因"),
                    PT("10/p-s8274f552", "然後，第三條這個諸佛同體。這是佛法社會觀的底層設定。我們佛法的社會觀就是以所有眾生的意識重疊在一起，這一點來構築出來的。你理解了這一點再看佛經，很多以前看不懂的內容都可以看得懂。", topic="諸佛同體為社會觀"),
                    PT("10/p-s8848e18c", "那麼我們看第二條，重新返回看第二條，這個初妄無因。從這裡延伸出來的是妄想、分別、執著，這個我已經反覆地在講。這個諸法的時候是法，或者萬法的時候，說萬法的時候這個法，都是妄想、分別、執著的統稱。", topic="萬法即妄分執統稱"),
                    PT("10/p-s633c34e5", "那麼我講經，大家都已經前面聽過了這幾部經，就會知道，我講經都是用妄想、分別、執著這個基本框架，來重新解釋意識層面的部分。還有這個社會觀層面的，為什麼度人，為什麼發願這個問題，以諸佛同體來解釋。有了這幾個前提之後再重新看佛經，就可以看懂很多以前看不懂的內容，也可以有更深入的理解。", topic="以妄分執框架解經"),
                    PT("10/p-s49102966", "這麼講，我已經把前面已經講過的內容重新梳理了一遍。這又是為什麼？因為後面這個要講的《楞嚴經》它的內容很多，它會涉及到很多內容，一個是真相的部分就是七處徵心，這個內容是真相的部分，後面又講到了修行的部分，然後最後又講到了五十陰魔，它是在修行當中可能會遇到的一些問題等等，這些它講的內容很多，你要對佛法有大的框架，它就可以理解起來非常容易了。", topic="楞嚴內容多需大框架"),
